import com.example.codec.api.Codec;

public final class Base62Codec implements Codec {
    private static final String ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

    @Override
    public String encode(long id) {
        if (id < 0) throw new IllegalArgumentException("negative id");
        if (id == 0) return String.valueOf(ALPHABET.charAt(0));
        StringBuilder sb = new StringBuilder();
        while (id > 0) { sb.append(ALPHABET.charAt((int) (id % 62))); id /= 62; }
        return sb.reverse().toString();
    }

    @Override
    public long decode(String code) {
        long id = 0;
        for (char c : code.toCharArray()) {
            int v = ALPHABET.indexOf(c);
            if (v < 0) throw new IllegalArgumentException("bad char");
            id = id * 62 + v;
        }
        return id;
    }
}
